def _linearly_scale(
    inputmatrix: Any, inputmin: Any, inputmax: Any, outputmin: Any, outputmax: Any
) -> object {
    inputrange = inputmax - inputmin;
    outputrange = outputmax - outputmin;
    OutputMatrix = (((inputmatrix - inputmin) * outputrange) / inputrange) + outputmin;
